INSERT INTO "dynasty_groups" ("id","name","alt_names","scope","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","note") VALUES ('wuhu','五胡十六国','["十六国","五胡"]','cn',304,1,NULL,'year',439,12,NULL,'month',3648,5279,'304–439年五胡十六国；狭义自刘渊/李雄立国至北魏灭北凉。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('cheng-han','成汉','["成","成汉","汉","大成"]','巴氐',NULL,'cn','east_asia',304,1,NULL,'year',347,1,NULL,'year',3648,4164,'ochre',NULL,'wuhu','巴氐李氏于西晋末在益州建立的政权。李雄以成都为中心稳固统治；李寿一度改国号为汉，347年为东晋桓温所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-zhao','汉赵','["汉","汉赵","前赵","赵"]','匈奴',NULL,'cn','east_asia',304,1,NULL,'year',329,1,NULL,'year',3648,3948,'ochre',NULL,'wuhu','匈奴刘氏建立，初称汉，后刘曜改国号为赵，史称汉赵或前赵。政权曾攻陷洛阳、长安并终结西晋，后与石勒争夺华北，329年为后赵所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('jin-east','东晋','["晋"]',NULL,NULL,'cn','east_asia',317,1,NULL,'year',420,7,NULL,'month',3804,5046,'ochre',NULL,NULL,'司马睿于307年镇守建邺，在王导等支持下经营江南。西晋覆亡后，317年称晋王，318年称帝，晋室在建康延续，史称东晋。王导、谢安等士族及桓温、刘裕等掌兵重臣先后影响朝政；383年淝水之战挫败前秦南下，420年刘裕受禅建立宋，东晋结束。北方人口南迁推动了江南开发。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('jin-west','西晋','["晋","司马晋"]',NULL,NULL,'cn','east_asia',249,2,5,'day',316,12,NULL,'month',2989,3803,'ochre',NULL,NULL,'司马氏在曹魏末逐步掌握军政：249年司马懿发动高平陵之变，司马师、司马昭先后执掌魏廷，以洛阳为政治中心；263年司马昭受封晋公，264年进晋王，265年司马炎继承晋王及相国职位。266年司马炎受魏禅建立晋朝，定都洛阳，280年灭吴而统一。武帝死后，宫廷争权与八王之乱削弱中央；汉赵于311年攻陷洛阳、316年迫使长安朝廷出降，西晋覆亡。北方人口与士族大量南迁，晋室后来在江南延续统治。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liang-back','后凉','["凉"]','氐',NULL,'cn','east_asia',386,1,NULL,'year',403,1,NULL,'year',4632,4836,'ochre',NULL,'wuhu','吕光原为前秦将领，383年奉命征西域，东归时前秦已陷入分裂。386年攻取姑臧、控制凉州，随后建立后凉，396年称天王。吕光晚年继承纷争使河西割据加深，403年吕隆降后秦。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liang-front','前凉','["凉"]',NULL,NULL,'cn','east_asia',301,1,NULL,'year',376,1,NULL,'year',3612,4512,'ochre',NULL,'wuhu','张氏据河西建立的政权，长期奉晋正朔而实际独立，以姑臧为中心。张骏时期势力最盛，376年向前秦出降。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liang-north','北凉','["凉"]','卢水胡匈奴',NULL,'cn','east_asia',397,1,NULL,'year',439,1,NULL,'year',4764,5268,'ochre',NULL,'wuhu','397年沮渠男成、蒙逊起兵反后凉，拥立建康太守段业，北凉由此建立。398年段业迁治张掖，401年蒙逊杀段业、自掌政权，412年迁都姑臧，逐步兼并河西诸国。439年北魏攻陷姑臧，北凉在河西的统治结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liang-south','南凉','["凉"]','秃发鲜卑',NULL,'cn','east_asia',397,1,NULL,'year',414,1,NULL,'year',4764,4968,'ochre',NULL,'wuhu','秃发氏在河湟长期经营部众，秃发乌孤于397年脱离后凉、建立南凉，初据廉川，399年迁乐都。其弟利鹿孤、傉檀相继统治，先后以西平、乐都、姑臧为中心，与后凉、北凉、西秦争战；414年西秦攻取乐都，南凉灭亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('liang-xi','西凉','["凉"]',NULL,NULL,'cn','east_asia',400,1,NULL,'year',421,1,NULL,'year',4800,5052,'ochre',NULL,'wuhu','400年敦煌地方官民推戴李暠，西凉由此建立，初都敦煌，405年迁酒泉。420年李歆败死于北凉，酒泉失守，其弟李恂在敦煌续立；421年北凉攻陷敦煌，李恂自杀，西凉结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qin-back','后秦','["秦"]','羌',NULL,'cn','east_asia',384,1,NULL,'year',417,1,NULL,'year',4608,5004,'ochre',NULL,'wuhu','羌族姚氏建立、据有关中的政权，姚兴时期扩张并支持佛教译经事业。姚兴死后内乱与刘裕北伐并至，417年后秦亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qin-front','前秦','["秦"]','氐',NULL,'cn','east_asia',350,1,NULL,'year',394,1,NULL,'year',4200,4728,'ochre',NULL,'wuhu','氐族苻氏据关中建立的政权。苻坚、王猛整合北方诸国，淝水之战后诸地相继割据，394年为西秦所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qin-xi','西秦','["秦"]','乞伏鲜卑',NULL,'cn','east_asia',385,1,NULL,'year',431,1,NULL,'year',4620,5172,'ochre',NULL,'wuhu','鲜卑乞伏氏在陇西、河湟建立的政权，曾降后秦而复国，并灭南凉。431年乞伏暮末降胡夏，西秦结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xia-hu','胡夏','["大夏","夏"]','匈奴',NULL,'cn','east_asia',407,1,NULL,'year',431,1,NULL,'year',4884,5172,'ochre',NULL,'wuhu','匈奴铁弗部赫连氏建立，以统万城为都，控制河套并向关中扩张。赫连昌被北魏俘获后国势衰退，431年赫连定被俘，胡夏亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yan-back','后燕','["燕"]','慕容鲜卑',NULL,'cn','east_asia',384,1,NULL,'year',409,1,NULL,'year',4608,4908,'ochre',NULL,'wuhu','慕容垂于淝水之战后复兴慕容政权，定都中山并控制河北。慕容垂死后皇位更迭、北魏南进，407年为冯跋所取代。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yan-front','前燕','["燕"]','慕容鲜卑',NULL,'cn','east_asia',337,1,NULL,'year',370,1,NULL,'year',4044,4440,'ochre',NULL,'wuhu','鲜卑慕容氏据辽东建立的政权，后迁都邺城并扩展至华北。慕容儁灭冉魏后国势达峰，370年为前秦所灭。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yan-north','北燕','["燕"]',NULL,NULL,'cn','east_asia',407,1,NULL,'year',436,1,NULL,'year',4884,5232,'ochre',NULL,'wuhu','407年冯跋等推翻后燕慕容熙，拥立高云，通常以此为北燕开端；409年高云被杀后冯跋即位。以和龙为中心，436年北魏攻取和龙，冯弘出奔，北燕终结。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('yan-south','南燕','["燕"]','慕容鲜卑',NULL,'cn','east_asia',398,1,NULL,'year',410,1,NULL,'year',4776,4920,'ochre',NULL,'wuhu','后燕河北地区被北魏夺取后，慕容德于398年率部南移滑台，称燕王，建立南燕；399年转据青州、都广固，400年称帝。410年刘裕攻陷广固，慕容超被俘，南燕灭亡。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhao-back','后赵','["赵","魏"]','羯',NULL,'cn','east_asia',319,1,NULL,'year',351,1,NULL,'year',3828,4212,'ochre',NULL,'wuhu','羯族石勒建立的政权，定都襄国、后迁邺，曾统治华北大部。石虎死后诸子争位并遭冉闵夺权，石祗于351年败亡。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('duan-ye','段业','liang-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,401,1,NULL,'year','["君主"]','京兆人，曾为后凉杜进记室、建康太守。397年后凉战败、沮渠氏起兵，沮渠男成与蒙逊拥立段业为凉州牧、建康公，改元神玺，建立北凉；399年称凉王。其军政依赖沮渠氏，401年因蒙逊设计而杀男成，随后被蒙逊攻杀。','[{"label":"《晋书》相关载记","url":"https://zh.wikisource.org/wiki/晉書/卷129"}]',NULL,NULL,'凉王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-ba','冯跋','yan-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','长乐信都人，父冯安曾任西燕将领，家族在西燕灭亡后迁入后燕。407年与冯素弗等发动政变，杀慕容熙，拥立高云，自己掌握军政；409年高云被近侍杀害，冯跋获群臣拥立为天王。以和龙为都，整顿赋役并与北魏、东晋交涉，430年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯跋"},{"label":"《晋书》卷125·冯跋载记","url":"https://zh.wikisource.org/wiki/晉書/卷125"}]','文成皇帝',NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('feng-hong','冯弘','yan-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','冯跋之弟，430年继位；北魏持续攻取北燕城地，436年和龙陷落后率众逃往高句丽，后被高句丽王所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯弘"},{"label":"資治通鑑/卷122","url":"https://zh.wikisource.org/wiki/資治通鑑/卷122"}]','昭成帝',NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-chong','苻崇','qin-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','苻登之子，394年继位后退保湟中；同年为西秦乞伏乾归击败并杀死，前秦亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻崇"}]',NULL,NULL,'前秦末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-deng','苻登','qin-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','苻坚族孙，386年在枹罕即位，凭借羌氐部众与后秦长期争战；394年兵败被姚兴俘杀，前秦仅余苻崇一支。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻登"}]','高皇帝','太宗','前秦高皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-jian','苻健','qin-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','苻洪之子。苻氏部众原属后赵，后赵内乱时苻洪率部转向关中；350年苻洪被毒杀，苻健继领部众，攻取长安。351年称天王、大单于，国号秦，352年称帝。他依靠氐族部众并任用汉人士人，巩固关中统治，355年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻健"}]','景明皇帝','高祖','前秦景明皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-jian-ming','苻坚','qin-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','苻健族孙，357年推翻苻生即位；任用王猛改革并先后灭前燕、前凉及代国，统一北方，383年南征败于淝水，帝国随即瓦解，苻坚于385年被姚苌杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻坚"}]','宣昭皇帝','世祖','前秦宣昭皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-pi','苻丕','qin-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','苻坚长子，淝水败后于385年在晋阳称帝，收集前秦余部；东晋北伐与后秦进攻令其势力受挫，386年战败被东晋将领冯该杀死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻丕"}]','哀平皇帝',NULL,'前秦哀平皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-sheng','苻生','qin-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','苻健之子，355年继位；统治以严酷猜忌著称，357年被堂弟苻坚废杀，前秦政权转向整合扩张。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻生"}]',NULL,NULL,'前秦废帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-yun-yan','高云','yan-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,409,1,NULL,'year','["君主"]','高句丽王族后裔，原为后燕官员，受慕容宝收养后改姓慕容。407年冯跋等发动政变、杀慕容熙，拥立高云为天王；他恢复高姓，以和龙为都，军政主要由冯跋掌握。409年被近侍杀害，冯跋继位。','[{"label":"《晋书》相关载记","url":"https://zh.wikisource.org/wiki/晉書/卷124"}]',NULL,NULL,'天王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gu-kaizhi','顾恺之','jin-east','[]',NULL,NULL,348,1,NULL,'year',409,1,NULL,'year','["画家"]','东晋画家，字长康，小字虎头，晋陵无锡人。擅长人物画与绘画理论，提出“以形写神”等主张；《女史箴图》《洛神赋图》传为其作，现存本均非确证真迹。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顾恺之"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('helian-bobo','赫连勃勃','xia-hu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','匈奴铁弗首领刘卫辰之子，原名刘勃勃。391年父亲败亡后逃往高平，后依附后秦，取得军队及部众；407年杀岳父没弈干、兼并其部，称天王、大单于，国号夏。413年营建统万城，418年攻占长安后称帝；425年传位赫连昌，随后去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赫连勃勃"}]','武皇帝',NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('helian-chang','赫连昌','xia-hu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','赫连勃勃之子，425年继位；北魏攻夏后于427年失统万城，428年被俘，胡夏主力退守关中。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赫连昌"}]',NULL,NULL,'胡夏皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('helian-ding','赫连定','xia-hu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','赫连勃勃之子，赫连昌被俘后于428年继位；431年灭西秦后西行，旋为吐谷浑所俘并送交北魏处死，胡夏亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赫连定"},{"label":"資治通鑑/卷121","url":"https://zh.wikisource.org/wiki/資治通鑑/卷121"}]',NULL,NULL,'胡夏末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('huan-wen','桓温','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','东晋权臣、将领，出身谯国桓氏，长期控制朝政并三次北伐。前两次北伐一度收复洛阳等地；太和六年废海西公、拥立司马昱，后谋求禅代未成，病逝于姑孰。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/桓温"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jia-nanfeng','贾南风','jin-west','[]',NULL,NULL,257,1,NULL,'year',300,1,NULL,'year','["皇后","政治家"]','西晋皇后，出身贾氏，晋惠帝司马衷之妻。惠帝即位后长期干预朝政，先后排斥外戚与政敌；元康年间杀太子司马遹，引发宫廷冲突，后被赵王司马伦废杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/贾南风"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('juqu-mengxun','沮渠蒙逊','liang-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','临松卢水胡人。397年因叔父被吕光杀害而起兵，与沮渠男成拥立建康太守段业，北凉由此建立。401年利用段业与男成的矛盾，先使段业杀男成，再攻杀段业，自任凉州牧。412年攻取姑臧并迁都，继而兼并西凉，与北魏、刘宋等保持往来；433年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/沮渠蒙逊"},{"label":"《晋书》卷129·沮渠蒙逊载记","url":"https://zh.wikisource.org/wiki/晉書/卷129"}]','武宣王',NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('juqu-mujian','沮渠牧犍','liang-north','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','沮渠蒙逊之子，433年继位；北魏太武帝于439年攻陷姑臧，沮渠牧犍出降并被迁往平城，北凉河西政权结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/沮渠牧犍"},{"label":"《资治通鉴》卷122","url":"https://zh.wikisource.org/wiki/資治通鑑/卷122"}]',NULL,NULL,'北凉末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-ban','李班','cheng-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李雄养子，李雄死后于334年继位；因非李氏宗亲且受宗室排斥，在位数月即被李越等杀害，成汉转入李期统治。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李班_(成汉)"}]','哀皇帝',NULL,'成汉哀皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-gao','李暠','liang-xi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','陇西成纪人，李昶之子，曾任效谷县令，后在段业统治下任敦煌太守。400年段业欲以索嗣取代他，李暠击败索嗣，获敦煌、晋昌等地支持，称凉公，建立西凉。405年将都城从敦煌迁至酒泉，与沮渠蒙逊争夺河西，417年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李暠"}]','武昭王',NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-qi','李期','cheng-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李雄之子，334年李越杀李班后即位；统治期间猜忌宗室、政局动荡，338年四月（原历）被李寿废为邛都县公，五月（原历）自缢。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李期"},{"label":"《资治通鉴》卷96（338年四月废李期、李寿即位改号，五月李期自缢）","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷096"},{"label":"中央研究院两千年中西历转换（咸康四年四月）","url":"https://sinocal.sinica.edu.tw/"}]','幽',NULL,'幽公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-shi','李势','cheng-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李寿之子，343年继位为汉帝；成汉在其统治下衰弱，347年东晋桓温伐蜀时出降，成汉亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李势"},{"label":"《资治通鉴》卷97","url":"https://zh.wikisource.org/wiki/資治通鑑/卷097"}]',NULL,NULL,'归义侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-shou','李寿','cheng-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李雄堂弟、李骧之子，曾镇守晋寿并率军攻取宁州，受封汉王。338年率军攻入成都，废李期即皇帝位，同年改国号为汉、改元汉兴。其后疏斥成旧臣，逐渐转向严苛统治并大兴营建；343年去世，由子李势继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李寿"},{"label":"《晋书》卷七·成帝纪（咸康四年夏四月李寿改国号汉）","url":"https://zh.wikisource.org/wiki/晉書/卷007"},{"label":"《资治通鉴》卷96（338年四月废李期、李寿即位改号，五月李期自缢）","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷096"},{"label":"中央研究院两千年中西历转换（咸康四年四月）","url":"https://sinocal.sinica.edu.tw/"}]','昭文皇帝','中宗','成汉昭文皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-xin','李歆','liang-xi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李暠之子，417年继位并迁都酒泉；与北凉争战失利，420年兵败被沮渠蒙逊杀害，西凉亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李歆"},{"label":"資治通鑑/卷118","url":"https://zh.wikisource.org/wiki/資治通鑑/卷118"}]',NULL,NULL,'西凉末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-xiong','李雄','cheng-han','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','李特之子，随家族率领入蜀流民。301年李特因安置、遣返流民问题起兵；303年李特、李流相继去世，李雄接掌军队。304年攻取成都，称成都王，306年称帝，国号成。他以流民军和蜀地为基础扩大统治，334年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李雄_(十六国)"},{"label":"人物生平与建国经历","url":"https://zh.wikipedia.org/wiki/李雄"}]','武皇帝','太宗','成汉武皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-can','刘粲','han-zhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘聪之子，318年继位；外戚靳准发动政变，刘粲即位不久即被杀，汉赵一度分裂，后由刘曜收拾局面。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘粲"}]','隐皇帝',NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-cong','刘聪','han-zhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘渊第四子，310年杀刘和夺位；在位期间扩张汉赵，311年攻陷洛阳俘晋怀帝、316年迫降晋愍帝，后期朝政受外戚与近臣干预。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘聪"}]','昭武皇帝',NULL,'汉赵昭武皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-he-zhao','刘和','han-zhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘渊嫡长子，310年继位；即位后欲清除掌兵的兄弟，旋被刘聪发动政变杀死，在位仅七日。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘和"}]',NULL,NULL,'汉赵皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yao-jin','刘曜','han-zhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','刘渊族子、刘聪养子，318年平定靳准之乱后继位；319年迁都长安并改国号为赵，统治关中，与石勒争衡，329年兵败被后赵俘杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘曜"}]',NULL,NULL,'末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yu-jin','刘裕','song-liu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家","政治家"]','彭城人，早年进入东晋北府军，399年起参与镇压孙恩。404年与刘毅等起兵讨伐篡晋的桓玄，迎回晋安帝，逐渐掌握朝政；又消灭刘毅等竞争者，410年灭南燕、417年灭后秦。420年受晋恭帝禅让建立宋朝，以建康为都，422年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘裕"},{"label":"《宋书·武帝纪》（维基文库）","url":"https://zh.wikisource.org/wiki/宋書/卷01"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-yuan','刘渊','han-zhao','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','匈奴南单于后裔、刘豹之子，曾在洛阳任晋官，后统领匈奴五部。八王之乱中参与司马颖军事，304年返回并州，获得五部支持后称汉王，国号汉，借与汉室的婚姻关系宣示继统。其军队乘晋朝内乱扩张，308年称帝，309年迁都平阳，310年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘渊"}]','光文皇帝','高祖','汉赵光文皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-guang','吕光','liang-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','苻坚部将、吕婆楼之子，前秦末年受命率军征服西域。东返时得知苻坚已死，385年夺取凉州姑臧，自行掌握当地军政；386年建元，389年称三河王，396年称天王，建立后凉。晚年河西诸势力相继独立，399年传位吕绍后去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吕光"}]','武皇帝',NULL,'后凉武皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-long','吕隆','liang-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','吕光之侄，401年由吕超拥立；后凉已被北凉、南凉夹击，403年向后秦姚兴出降，后凉亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吕隆"},{"label":"資治通鑑/卷112","url":"https://zh.wikisource.org/wiki/資治通鑑/卷112"}]',NULL,NULL,'后凉末主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lu-zuan','吕纂','liang-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','吕光之子，399年杀兄吕绍夺位；统治期间持续面对沮渠蒙逊等势力挑战，401年被弟吕超所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吕纂"}]','灵帝',NULL,'后凉灵帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-bao','慕容宝','yan-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容垂第四子，396年继位；次年参合陂之败削弱后燕，慕容宝退守中山，398年为兰汗所杀，后燕陷入分裂。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容宝"}]','惠愍皇帝','烈宗','后燕惠愍皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-chao','慕容超','yan-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容德侄，405年继位；南燕与东晋冲突不断，刘裕于409年北伐围攻广固，410年城陷，慕容超被俘送建康处死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容超"},{"label":"資治通鑑/卷114","url":"https://zh.wikisource.org/wiki/資治通鑑/卷114"},{"label":"晉書/卷127","url":"https://zh.wikisource.org/wiki/晉書/卷127"}]',NULL,NULL,'南燕末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-chui','慕容垂','yan-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容皝之子，原为前燕将领。369年因与慕容评等冲突而投奔前秦；前秦灭前燕后，他仍统领旧部。383年淝水战败后获准返回河北，384年起兵复燕，386年称帝、定都中山。394年灭西燕，次年参合陂之战败于北魏，396年亲征途中病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容垂"}]','成武皇帝','世祖','后燕成武皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-de-yan','慕容德','yan-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容皝之子、慕容垂之弟，曾掌后燕南部军队。北魏攻占后燕河北地区后，398年率部南移滑台，称燕王，建立南燕；399年转据青州并以广固为都，400年称帝。其统治依靠慕容旧部与当地士族，405年去世，慕容超继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容德"},{"label":"資治通鑑/卷114","url":"https://zh.wikisource.org/wiki/資治通鑑/卷114"},{"label":"晉書/卷127","url":"https://zh.wikisource.org/wiki/晉書/卷127"}]','献武皇帝',NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-huang','慕容皝','yan-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容廆第三子，333年继领鲜卑慕容部。平定慕容仁等宗室的争夺后，继续经营辽西，337年称燕王，建立前燕；341年迁都龙城，并击败后赵进攻、征伐高句丽等势力。348年去世，子慕容儁继位；前燕称帝是在慕容儁时期。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容皝"}]','文明皇帝',NULL,'前燕文明皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-jun','慕容儁','yan-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容皝之子，348年继位，352年称帝；迁都邺城并灭冉魏，前燕疆域扩至华北，360年死后由子慕容暐继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容儁"},{"label":"資治通鑑/卷101","url":"https://zh.wikisource.org/wiki/資治通鑑/卷101"}]','景昭皇帝',NULL,'前燕景昭皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-sheng','慕容盛','yan-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容宝庶长子，398年兰汗篡位时暂避龙城，随后起兵诛兰汗复国；在位期间平定内乱，401年为部将所杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容盛"}]','昭武皇帝','中宗','','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-wei','慕容暐','yan-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容儁之子，幼年即位，政务由慕容恪等辅佐；慕容恪死后朝政失衡，370年苻坚攻陷邺城，前燕亡，慕容暐降秦。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容暐"},{"label":"資治通鑑/卷101","url":"https://zh.wikisource.org/wiki/資治通鑑/卷101"}]',NULL,NULL,'前燕末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-xi','慕容熙','yan-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容垂幼子，401年继位；后燕内政失序，407年冯跋起兵，慕容熙被俘杀，后燕结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容熙"}]',NULL,NULL,'后燕末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('murong-yi','慕容义','yan-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','慕容宝之子，407年短暂继位于后燕；同年冯跋发动政变将其废杀，后燕政权由冯氏接掌。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容义"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qifu-chipan','乞伏炽磐','qin-xi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','乞伏乾归长子，412年继位；西秦势力复振，414年灭南凉并据有河湟，428年去世后由子乞伏暮末继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乞伏炽磐"}]','文昭王','太祖','','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qifu-gan','乞伏乾归','qin-xi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','乞伏国仁之弟，388年继位并称河南王，后称秦王；一度降附后秦、出奔南凉，409年复国，412年被部下杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乞伏乾归"}]','文威皇帝',NULL,'西秦文威皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qifu-guoren','乞伏国仁','qin-xi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','鲜卑乞伏部首领乞伏司繁之子，376年父死后继领部众，受前秦任用。383年前秦命其返乡平叛，他转而联合部众扩张；前秦在淝水战败后难以控制陇西，乞伏国仁于385年称大单于、建元建义，以勇士城为据点建立西秦。388年去世，弟乞伏乾归继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乞伏国仁"}]','武元王',NULL,'西秦武元王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qifu-mumo','乞伏暮末','qin-xi','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','乞伏炽磐之子，428年继位；遭夏军进逼后于431年降夏，西秦灭亡，随后被赫连定杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乞伏暮末"},{"label":"資治通鑑/卷121","url":"https://zh.wikisource.org/wiki/資治通鑑/卷121"}]',NULL,NULL,'西秦末主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-hong','石弘','zhao-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','石勒之子，333年继位；政权实权掌握在石虎手中，石虎于翌年废杀石弘并夺位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石弘"}]',NULL,NULL,'后赵皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-hu','石虎','zhao-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','石勒养子，334年废石弘自立，后称帝并迁都邺城；大举营建与频繁征伐加重国力消耗，其死后诸子争位，后赵迅速分裂。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石虎"},{"label":"《资治通鉴》卷95","url":"https://zh.wikisource.org/wiki/資治通鑑/卷095"},{"label":"資治通鑑/卷098","url":"https://zh.wikisource.org/wiki/資治通鑑/卷098"}]','武皇帝','太祖','后赵武皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-jian','石鉴','zhao-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','石虎之子，石遵死后于349年被冉闵拥立；次年冉闵杀石鉴并控制邺城，石氏政权失去中枢。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石鉴"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-le','石勒','zhao-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','羯人，晋末曾被掠卖为奴，脱身后聚众起兵，归附刘渊的汉政权，逐渐成为重要将领。312年据襄国，经营河北；刘曜于319年改国号赵后，石勒与之决裂，称赵王，建立后赵。329年灭前赵，330年称帝，333年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石勒"}]','明皇帝','高祖','后赵明皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-shi','石世','zhao-back','[]',NULL,NULL,339,1,NULL,'year',349,6,NULL,'month','["皇帝"]','石虎幼子，349年石虎死后由太后拥立；在位三十三日即被石遵废杀，后赵进入连续政变。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石世"},{"label":"資治通鑑/卷098","url":"https://zh.wikisource.org/wiki/資治通鑑/卷098"}]',NULL,NULL,'少帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-zhi','石祗','zhao-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','石虎之子，冉闵杀石鉴后在襄国称帝，延续石氏后赵；351年被部将刘显攻杀，后赵正式灭亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石祗"}]',NULL,NULL,'末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('shi-zun','石遵','zhao-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','石虎之子，349年废杀石世自立；因未能安抚诸军，同年被冉闵发动兵变杀死。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石遵"}]',NULL,NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-chi','司马炽','jin-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','司马炎之子、惠帝之弟，307年在东海王司马越等拥立下即位。皇权受宗王与权臣牵制；311年汉赵军攻陷洛阳，他被俘至平阳，西晋仍由长安朝廷延续，313年遇害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马炽"}]','孝怀皇帝',NULL,'晋怀帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-dan','司马聃','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','司马岳之子，344年幼年即位，朝政先后由褚太后及权臣辅佐。桓温在其朝掌握荆州兵力并发动多次北伐，356年收复洛阳；北伐未能恢复中原，中央对强藩的依赖加深，司马聃于361年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马聃"}]','孝穆皇帝',NULL,'晋穆帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-dewen','司马德文','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','司马曜之子、安帝之弟，419年在刘裕控制下继位。此时东晋的军事与政务已由刘裕掌握，刘裕于420年迫使其禅位、建立刘宋；司马德文被降封零陵王，次年遇害，东晋至此结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马德文"}]','孝恭皇帝',NULL,'晋恭帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-dezong','司马德宗','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','司马曜长子，396年继位，朝政由会稽王司马道子等掌握。孙恩起义、桓玄篡位使东晋一度失去统治，刘裕起兵平乱并于404年迎复安帝；刘裕随后掌握军政大权，司马德宗于419年被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马德宗"}]','孝安皇帝',NULL,'晋安帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-lun','司马伦','jin-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,301,6,NULL,'month','["皇帝"]','司马懿第九子，封赵王，参与八王之乱。301年篡晋惠帝位，自立为帝并改元建始；同年败亡，惠帝复位后被赐死。','[{"label":"《晋书·赵王伦传》","url":"https://zh.wikisource.org/wiki/晉書/卷059"},{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马伦"}]',NULL,NULL,'赵王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-pi','司马丕','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','司马岳之子、穆帝之兄，361年继位。朝政受褚太后、会稽王司马昱及桓温等人影响；前一朝桓温北伐曾短暂收复洛阳，东晋的北方进取仍未稳固。史载他服食丹药求长生，365年去世且无子，皇位由弟司马奕承继。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马丕"}]','孝哀皇帝',NULL,'晋哀帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-rui','司马睿','jin-east','[]',NULL,NULL,276,1,NULL,'year',323,1,NULL,'year','["皇帝"]','晋宗室，司马觐之子。307年出镇建邺，在王导等人支持下联结南渡士族与江南士族，形成江东统治基础。316年长安陷落、晋愍帝被俘后，317年在建康称晋王，318年称帝，延续晋朝。朝政受到王氏势力制约，322年王敦起兵攻入建康。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马睿"}]','元皇帝','中宗','晋元帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-shao','司马绍','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','司马睿之子，323年继位。即位初即面对王敦之乱，亲自部署平乱并恢复建康朝廷的控制；他试图整顿政务、压低强藩影响，但在位仅两年，325年去世，皇位传给年幼的长子司马衍。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马绍"}]','孝明皇帝','肃宗','晋明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-shi','司马师','jin-west','[]',NULL,NULL,208,1,NULL,'year',255,3,23,'day','["政治家","军事家"]','司马懿与张春华长子，司马昭之兄。249年参与高平陵之变，251年父亲去世后袭舞阳侯、以抚军大将军辅政，次年升大将军，总领魏廷军政。254年诛李丰、夏侯玄等，废曹芳、立曹髦；255年亲征毌丘俭、文钦，平乱后病逝于许昌，司马昭继掌军政。后来追尊晋景王，晋朝建立后追尊景皇帝，庙号世宗。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马师"},{"label":"《晋书·景帝纪、文帝纪》","url":"https://zh.wikisource.org/zh-hans/晉書/卷002"},{"label":"《三国志·三少帝纪》","url":"https://zh.wikisource.org/zh-hans/三國志/卷04"},{"label":"正始 (曹魏)纪年农历对照表","url":"https://zh.wikipedia.org/wiki/正始_(曹魏)"},{"label":"嘉平 (曹魏)纪年农历对照表","url":"https://zh.wikipedia.org/wiki/嘉平_(曹魏)"},{"label":"正元 (曹魏)纪年农历对照表","url":"https://zh.wikipedia.org/wiki/正元_(曹魏)"},{"label":"景元纪年农历对照表","url":"https://zh.wikipedia.org/wiki/景元"},{"label":"咸熙纪年农历对照表","url":"https://zh.wikipedia.org/wiki/咸熙"}]','忠武侯,景王,景皇帝','世宗',NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-yan','司马炎','jin-west','[]',NULL,NULL,236,1,NULL,'year',290,1,NULL,'year','["皇帝"]','司马昭之子。司马懿于249年高平陵政变后掌握魏廷，司马师、司马昭相继控制军政；263年魏军灭蜀，司马氏的势力进一步巩固。司马炎于265年继承晋王及相国职位，266年受魏元帝禅让建立晋朝，都洛阳。280年灭吴，结束三国分立；分封宗室与继承安排成为其死后宫廷、诸王争权的重要背景。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马炎"},{"label":"《晋书·武帝纪》","url":"https://zh.wikisource.org/zh-hans/晉書/卷003"},{"label":"《三国志·三少帝纪》","url":"https://zh.wikisource.org/zh-hans/三國志/卷04"},{"label":"景元纪年农历对照表","url":"https://zh.wikipedia.org/wiki/景元"},{"label":"咸熙纪年农历对照表","url":"https://zh.wikipedia.org/wiki/咸熙"}]','武皇帝','世祖','晋武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-yan-cheng','司马衍','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','司马绍长子，325年幼年即位，政务由庾太后与王导等辅政。327年苏峻起兵攻入建康，朝廷一度失去都城，后由陶侃、温峤等联军平乱；东晋恢复后政局趋稳，342年去世，由弟司马岳继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马衍"}]','孝成皇帝','显宗','晋成帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-yao','司马曜','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','司马昱之子，372年即位，初年由桓温及宗室辅政。383年，前秦苻坚大举南下，谢安、谢玄等主持抵抗，东晋在淝水之战获胜，北方统一攻势瓦解；此后皇权仍受宗室与强藩牵制，司马曜于396年遇害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马曜"}]','孝武皇帝',NULL,'晋孝武帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-ye','司马邺','jin-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','司马炽之侄，313年在长安即位，是西晋最后一位皇帝。即位时洛阳已陷，朝廷依靠关中守军维持；316年汉赵军围攻长安后出降，西晋灭亡，他被迁往平阳并于318年遇害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马邺"}]','孝愍皇帝',NULL,'晋愍帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-yi-jin','司马奕','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','司马岳之子、穆帝之兄，365年继位，史称海西公。桓温凭借荆州军力逐步控制朝政，并借北伐失利与皇帝失德之名施压；371年司马奕被废为东海王，东晋皇位转由司马昱承继。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马奕"}]','海西公',NULL,'晋海西公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-yu-jin','司马昱','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','司马睿之子、司马奕的叔父，长期担任辅政重臣，371年在桓温主导下即位。桓温意在迫使其禅位，司马昱未能摆脱权臣控制；他于372年去世，太子司马曜继位，桓温未能如愿受禅。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马昱"}]','简文皇帝',NULL,'晋简文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-yue','司马岳','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','司马绍之子、成帝之弟，342年承继皇位。东晋在其短暂统治期间由庾氏外戚辅政，北方后赵与前燕等势力持续变化；他在位约两年，344年去世，皇位传给年幼的儿子司马聃。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马岳"}]','孝康皇帝',NULL,'晋康帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-zhao','司马昭','jin-west','[]',NULL,NULL,211,1,NULL,'year',265,9,6,'day','["政治家","军事家","君主"]','司马懿与张春华次子，司马师之弟、司马炎之父。254年因拥立曹髦进封高都侯，255年继司马师掌握魏廷军政，平定诸葛诞之乱。260年曹髦讨伐司马氏，被贾充部下成济杀害，随后拥立曹奂。263年派邓艾、钟会等伐蜀，同年受命为相国、晋公，264年进晋王。265年在洛阳去世，司马炎继位；晋朝建立后追尊文皇帝，庙号太祖。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马昭"},{"label":"《晋书·景帝纪、文帝纪》","url":"https://zh.wikisource.org/zh-hans/晉書/卷002"},{"label":"《三国志·三少帝纪》","url":"https://zh.wikisource.org/zh-hans/三國志/卷04"},{"label":"正始 (曹魏)纪年农历对照表","url":"https://zh.wikipedia.org/wiki/正始_(曹魏)"},{"label":"嘉平 (曹魏)纪年农历对照表","url":"https://zh.wikipedia.org/wiki/嘉平_(曹魏)"},{"label":"正元 (曹魏)纪年农历对照表","url":"https://zh.wikipedia.org/wiki/正元_(曹魏)"},{"label":"景元纪年农历对照表","url":"https://zh.wikipedia.org/wiki/景元"},{"label":"咸熙纪年农历对照表","url":"https://zh.wikipedia.org/wiki/咸熙"}]','文王,文皇帝','太祖',NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sima-zhong','司马衷','jin-west','[]',NULL,NULL,259,2,NULL,'month',307,1,NULL,'year','["皇帝"]','司马炎之子，290年继位。301年司马伦篡位，司马衷被尊为太上皇；司马伦败亡后于同年复位。其统治期间爆发八王之乱，306年返回洛阳，307年1月8日去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/司马衷"}]','孝惠皇帝',NULL,'晋惠帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tao-yuanming','陶渊明','jin-east','[]',NULL,NULL,365,1,NULL,'year',427,1,NULL,'year','["诗人"]','东晋诗人，田园诗派开创者，桃花源记作者；《归去来兮辞》《饮酒》等作品传世；《桃花源记》描绘其理想中的社会图景。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陶渊明"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tufa-lilugu','秃发利鹿孤','liang-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','秃发乌孤之弟，399年继位；以广武为都并与后凉、北凉及西秦周旋，402年让位于弟秃发傉檀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秃发利鹿孤"}]',NULL,NULL,'南凉皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tufa-rutan','秃发傉檀','liang-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','秃发利鹿孤之弟，402年继位并迁都姑臧；多次与北凉及后秦交战，414年为西秦乞伏炽磐所灭，降后被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秃发傉檀"},{"label":"資治通鑑/卷112","url":"https://zh.wikisource.org/wiki/資治通鑑/卷112"}]',NULL,NULL,'南凉末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tufa-wugu','秃发乌孤','liang-south','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','鲜卑秃发部首领秃发思复鞬之子，394年继领部众，在河湟经营农牧及军事力量。曾接受后凉封授，397年脱离后凉，称西平王，建立南凉，以廉川为据点；398年改称武威王，399年迁都乐都，同年去世，弟秃发利鹿孤继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秃发乌孤"}]','武成王',NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-dao','王导','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','东晋开国重臣，与司马睿共定江南，王与马共天下；东晋初任丞相、司徒，协调皇室与江东士族；王氏影响常以“王与马，共天下”概括。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王导"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wang-xizhi','王羲之','jin-east','[]',NULL,NULL,303,1,NULL,'year',361,1,NULL,'year','["书法家"]','东晋书法家，字逸少，琅邪临沂人，官至会稽内史。工行、草、楷书，代表作《兰亭集序》被后世奉为行书典范，世称“书圣”；现存作品多为摹本。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王羲之"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xie-an','谢安','jin-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','东晋陈郡谢氏政治家，长期隐居东山，后出仕任宰相。淝水之战时主持朝政并协调谢玄等将领迎战前秦，战后谢氏声望大增；其从容应对成为后世典故。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/谢安"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('xie-xuan','谢玄','jin-east','[]',NULL,NULL,343,1,NULL,'year',388,1,NULL,'year','["军事家"]','东晋将领，陈郡谢氏成员，谢安侄。受命经营京口、组建北府兵，淝水之战中任前线主将，击败前秦军；此后参与北伐，收复黄河以南多地。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/谢玄"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yao-chang','姚苌','qin-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','羌族首领姚弋仲之子。357年兄姚襄战死后率部归附前秦，历任将领；384年前秦内乱时脱离苻坚，获得关中羌人支持，称万年秦王。385年俘杀苻坚，386年攻取长安并称帝，建立后秦。此后与苻登争夺关中，394年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姚苌"}]','武昭皇帝','太祖','后秦武昭皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yao-hong','姚泓','qin-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','姚兴之子，416年继位；内部宗室冲突削弱国力，刘裕北伐于417年攻陷长安，姚泓出降后被杀，后秦亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姚泓"}]',NULL,NULL,'后秦末帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yao-xing','姚兴','qin-back','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["皇帝"]','姚苌之子，394年继位；扩张后秦至关中、陇右及河西东部，提倡佛教并支持鸠摩罗什译经，晚年诸子争权，416年去世后后秦迅速衰弱。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姚兴"}]','文桓皇帝',NULL,'后秦文桓皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-chonghua','张重华','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张骏之子，346年继位；年少时由大臣辅政，持续抵御后赵及前秦压力，353年去世后由幼子张耀灵承位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张重华"}]','桓王',NULL,'前凉桓王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-gui','张轨','liang-front','["士彦"]',NULL,NULL,255,1,NULL,'year',314,6,20,'day','["君主"]','安定乌氏人，张温之子，历任西晋官职。301年出任凉州刺史，在姑臧整顿地方军政、发展农业并任用河西士人；晋朝内乱期间收纳流民，维持与晋廷的关系。314年去世，子张寔承袭凉州职位。张氏世袭统治由此形成，后世称前凉；张轨本人未称帝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张轨"},{"label":"太平御覽/0124","url":"https://zh.wikisource.org/wiki/太平御覽/0124"},{"label":"晉書/卷086","url":"https://zh.wikisource.org/wiki/晉書/卷086"}]','武公',NULL,'前凉武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-jun','张骏','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张寔之子，324年继位；前凉在其统治下势力扩展至西域和河西诸郡，名义上奉晋，成为张氏政权的强盛时期。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张骏_(十六国)"}]','文王',NULL,'前凉文王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-mao','张茂','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张寔之弟，320年继掌凉州；沿用晋年号并以晋臣自居，实际维持河西独立统治，修缮姑臧城并经营地方。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张茂_(前凉)"}]','成王',NULL,'前凉成王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-shi','张寔','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张轨之子，张轨死后于314年继掌凉州；承袭父亲保境安民、奉晋正朔的政策，抵御地方叛乱，奠定张氏河西政权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张寔"},{"label":"太平御覽/0124","url":"https://zh.wikisource.org/wiki/太平御覽/0124"},{"label":"晉書/卷086","url":"https://zh.wikisource.org/wiki/晉書/卷086"}]','昭王',NULL,'前凉昭王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-tianxi','张天锡','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张骏之子，363年夺位；前凉在前秦扩张下日益孤立，376年苻坚大军来攻时出降，张氏政权终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张天锡_(前凉)"},{"label":"資治通鑑/卷101","url":"https://zh.wikisource.org/wiki/資治通鑑/卷101"}]',NULL,NULL,'前凉末王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-xuanjing','张玄靓','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张重华之子，幼年继位，长期由张天锡等权臣辅政；363年张天锡发动政变，废张玄靓为凉王并将其杀害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张玄靓"}]','冲王',NULL,'前凉冲王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-zuo','张祚','liang-front','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','张骏之子，353年废杀侄子张耀灵夺位并称帝；统治失政，355年为张天锡等所杀，前凉恢复张氏宗室继承。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张祚_(前凉)"}]','威王',NULL,'前凉威王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zu-ti','祖逖','jin-east','[]',NULL,NULL,266,1,NULL,'year',321,1,NULL,'year','["军事家"]','东晋将领，范阳遒县人，早年与刘琨相友，以“闻鸡起舞”故事闻名。西晋末率部南渡，受命北伐并进驻豫州，收复黄河以南部分地区；病逝后北伐事业受挫。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/祖逖"}]',NULL,NULL,NULL,'[]');
