INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('feishui-battle','淝水之战','battle','point','year',NULL,NULL,'太元八年，383年，前秦败于东晋',383,12,NULL,4607,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'苻坚率百万大军南征东晋，于淝水惨败，前秦迅速崩溃，北方再分裂。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('fu-jian-unify-north','苻坚统一北方','politics','span',NULL,'year','year','370–376年，前秦先后灭前燕、前凉等',NULL,NULL,NULL,NULL,370,1,NULL,4440,376,1,NULL,4512,'苻坚任用王猛，先后灭前燕、前凉等，统一北方，为十六国最大疆域。',NULL,NULL,'[]');
