INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('jin-unify-wu','三国归晋','politics','point','month',NULL,NULL,'太康元年四月，280年',280,4,NULL,3363,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'晋军灭东吴，三国分裂终结，西晋完成统一。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('li-shou-change-country-name','李寿改国号为汉','politics','point','year',NULL,NULL,'咸康四年夏四月（原历），对应前推公历338年5月7日至6月4日；史料未记具体日，跨公历月，保留年精度。',338,12,NULL,4067,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'李寿发动政变废李期为邛都县公并即皇帝位，同年废“成”号、改国号为“汉”，改元汉兴，以承续汉朝统绪。改号后的政权仍是原成都政权的延续，后世为与其他汉政权区别而合称成汉；其后仍与东晋、后赵周旋，最终于347年为东晋桓温所灭。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('liu-yao-change-country-name','刘曜改国号为赵','politics','point','year',NULL,NULL,'光初二年六月，319年',319,12,NULL,3839,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'刘曜迁都长安后下令议改汉赵宗庙与国号，群臣据其功业及中山分野建议称“大赵”；刘曜采纳，并以冒顿配天、刘渊配上帝，汉赵由此改称赵，后世称前赵。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('liu-yu-north','刘裕北伐','battle','point','year',NULL,NULL,'416–417年，刘裕灭后秦',417,12,NULL,5015,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'刘裕率军北伐，攻占长安，灭后秦，东晋势力达于极北。',NULL,NULL,'[]');
